index|idx_decision_ledger_session|decision_ledger|CREATE INDEX idx_decision_ledger_session ON decision_ledger(session_id, id)
index|idx_landing_commits_session|landing_commits|CREATE INDEX idx_landing_commits_session ON landing_commits(session_id, id)
index|idx_memory_entries_session|memory_entries|CREATE INDEX idx_memory_entries_session ON memory_entries(session_id, id)
index|idx_merge_candidates_artifact|merge_candidates|CREATE INDEX idx_merge_candidates_artifact ON merge_candidates(artifact_id)
index|idx_messages_dedup|messages|CREATE UNIQUE INDEX idx_messages_dedup ON messages(session_id, dedup_key) WHERE dedup_key IS NOT NULL
index|idx_messages_history|messages|CREATE INDEX idx_messages_history\n            ON messages(session_id, id DESC)\n            WHERE role IN ('user','assistant')
index|idx_messages_session|messages|CREATE INDEX idx_messages_session ON messages(session_id, id)
index|idx_remote_inbox_pending|remote_inbox|CREATE INDEX idx_remote_inbox_pending ON remote_inbox(session_id, id) WHERE delivered_at IS NULL AND failed_at IS NULL
index|idx_reviews_artifact|reviews|CREATE INDEX idx_reviews_artifact ON reviews(artifact_id)
index|idx_run_commits_session|run_commits|CREATE INDEX idx_run_commits_session ON run_commits(session_id, id)
index|idx_team_run_pending_session|team_run_pending|CREATE INDEX idx_team_run_pending_session ON team_run_pending(session_id, id)
