table|acceptance_criteria|acceptance_criteria|CREATE TABLE acceptance_criteria (\n            id TEXT PRIMARY KEY,\n            session_id TEXT NOT NULL,\n            run_id TEXT NOT NULL,\n            task_id TEXT NOT NULL,\n            contract_id TEXT,\n            scope TEXT NOT NULL DEFAULT 'task' CHECK (scope IN ('run', 'task')),\n            claim TEXT NOT NULL,\n            verifier TEXT,\n            evidence TEXT,\n            status TEXT NOT NULL DEFAULT 'pending'\n                CHECK (status IN ('pending', 'passed', 'failed', 'waived')),\n            waiver TEXT,\n            created_at INTEGER NOT NULL\n        )
table|agents|agents|CREATE TABLE agents (\n            id TEXT NOT NULL PRIMARY KEY,\n            name TEXT NOT NULL,\n            access TEXT NOT NULL\n                CHECK (access IN ('native', 'borrow', 'harness')),\n            provider TEXT NOT NULL,\n            primary_model TEXT,\n            endpoint TEXT,\n            auth_mode TEXT\n                CHECK (auth_mode IS NULL OR auth_mode IN ('bearer', 'x_api_key')),\n            model_opus TEXT,\n            model_sonnet TEXT,\n            model_haiku TEXT,\n            model_subagent TEXT,\n            reasoning_default TEXT NOT NULL DEFAULT 'auto'\n                CHECK (reasoning_default IN ('auto', 'none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max')),\n            max_output_tokens INTEGER,\n            api_timeout_ms INTEGER,\n            compat_disable_betas INTEGER NOT NULL DEFAULT 0,\n            compat_disable_nonessential INTEGER NOT NULL DEFAULT 0,\n            compat_disable_thinking INTEGER NOT NULL DEFAULT 0,\n            compat_proxy TEXT,\n            custom_headers TEXT,\n            extra_body TEXT,\n            cap_reasoning TEXT,\n            cap_computer_use TEXT,\n            cap_lead TEXT,\n            has_key INTEGER NOT NULL DEFAULT 0,\n            is_builtin INTEGER NOT NULL DEFAULT 0,\n            enabled INTEGER NOT NULL DEFAULT 1,\n            sort_order INTEGER NOT NULL DEFAULT 0,\n            created_at INTEGER NOT NULL,\n            updated_at INTEGER NOT NULL\n        )
table|app_settings|app_settings|CREATE TABLE app_settings (\n            key TEXT PRIMARY KEY,\n            value TEXT NOT NULL\n        )
table|artifacts|artifacts|CREATE TABLE artifacts (\n            id TEXT PRIMARY KEY,\n            session_id TEXT NOT NULL,\n            run_id TEXT NOT NULL,\n            member_assignment_id TEXT NOT NULL,\n            branch TEXT NOT NULL,\n            base_sha TEXT NOT NULL,\n            commit_sha TEXT,\n            files_changed INTEGER NOT NULL DEFAULT 0,\n            state TEXT NOT NULL DEFAULT 'finalizing'\n                CHECK (state IN ('finalizing','ready','merged','discarded')),\n            created_at INTEGER NOT NULL\n        )
table|attachments|attachments|CREATE TABLE attachments (\n            id TEXT PRIMARY KEY,\n            session_id TEXT NOT NULL,\n            kind TEXT NOT NULL,\n            sha256 TEXT NOT NULL,\n            media_type TEXT,\n            byte_size INTEGER,\n            rel_path TEXT NOT NULL,\n            width INTEGER,\n            height INTEGER,\n            created_at INTEGER NOT NULL\n        )
table|checkpoint_entries|checkpoint_entries|CREATE TABLE checkpoint_entries (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            session_id TEXT NOT NULL,\n            run_id TEXT NOT NULL,\n            member_id TEXT,\n            file_path TEXT NOT NULL,\n            existed INTEGER NOT NULL,\n            blob_sha TEXT,\n            file_mode INTEGER,\n            is_symlink INTEGER NOT NULL DEFAULT 0,\n            pre_xattrs BLOB,\n            allowed_root TEXT,\n            post_sha TEXT,\n            post_missing INTEGER NOT NULL DEFAULT 0,\n            post_file_type TEXT,\n            post_mode INTEGER,\n            post_nlink INTEGER,\n            post_inode INTEGER,\n            post_xattr_sha TEXT,\n            post_tainted INTEGER NOT NULL DEFAULT 0,\n            undone_at INTEGER,\n            created_at INTEGER NOT NULL,\n            UNIQUE (session_id, run_id, file_path)\n        )
table|daily_report|daily_report|CREATE TABLE daily_report (\n                repo_id TEXT PRIMARY KEY REFERENCES repos(id) ON DELETE CASCADE,\n                content TEXT NOT NULL,\n                generated_at INTEGER NOT NULL,\n                head_sha TEXT NOT NULL\n            )
table|decision_ledger|decision_ledger|CREATE TABLE decision_ledger (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            session_id TEXT NOT NULL,\n            run_id TEXT,\n            source_assignment_id TEXT,\n            text TEXT NOT NULL,\n            source_refs_json TEXT NOT NULL DEFAULT '[]',\n            supersedes_json TEXT NOT NULL DEFAULT '[]',\n            source_kind TEXT,\n            confidence TEXT,\n            created_at INTEGER NOT NULL\n        )
table|goal_contracts|goal_contracts|CREATE TABLE goal_contracts (\n            id TEXT PRIMARY KEY,\n            session_id TEXT NOT NULL,\n            run_id TEXT NOT NULL UNIQUE,\n            goal TEXT NOT NULL,\n            lead_participant_id TEXT NOT NULL,\n            status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'frozen')),\n            assignments_json TEXT NOT NULL DEFAULT '[]',\n            created_at INTEGER NOT NULL,\n            goal_title TEXT\n        )
table|landing_commits|landing_commits|CREATE TABLE landing_commits (\n            id TEXT PRIMARY KEY,\n            session_id TEXT NOT NULL,\n            run_id TEXT NOT NULL,\n            artifact_id TEXT,\n            pre_head TEXT NOT NULL,\n            landed_head TEXT NOT NULL,\n            commit_count INTEGER NOT NULL DEFAULT 0,\n            files_changed INTEGER NOT NULL DEFAULT 0,\n            insertions INTEGER NOT NULL DEFAULT 0,\n            deletions INTEGER NOT NULL DEFAULT 0,\n            created_at INTEGER NOT NULL,\n            UNIQUE(session_id, run_id, landed_head)\n        )
table|lead_loop_state|lead_loop_state|CREATE TABLE lead_loop_state (\n            session_id TEXT PRIMARY KEY,\n            autonomy TEXT NOT NULL DEFAULT 'cautious'\n                CHECK (autonomy IN ('cautious','handsfree','auto')),\n            active_run_id TEXT,\n            active_task_id TEXT,\n            last_event_cursor TEXT,\n            updated_at INTEGER NOT NULL\n        )
table|member_report_delivery|member_report_delivery|CREATE TABLE member_report_delivery (\n            session_id TEXT NOT NULL,\n            message_id INTEGER NOT NULL,\n            assignment_id TEXT,\n            delivered_at INTEGER,\n            PRIMARY KEY (session_id, message_id)\n        )
table|memory_blocks|memory_blocks|CREATE TABLE memory_blocks (\n            session_id TEXT NOT NULL,\n            slot TEXT NOT NULL,\n            text TEXT NOT NULL,\n            title TEXT,\n            anchor_refs_json TEXT NOT NULL DEFAULT '[]',\n            updated_by TEXT,\n            updated_at INTEGER NOT NULL,\n            revision INTEGER NOT NULL DEFAULT 0,\n            updated_run_id TEXT,\n            PRIMARY KEY (session_id, slot)\n        )
table|memory_entries|memory_entries|CREATE TABLE memory_entries (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            session_id TEXT NOT NULL,\n            category TEXT NOT NULL,\n            text TEXT NOT NULL,\n            source_refs_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(source_refs_json)),\n            supersedes_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(supersedes_json)),\n            source TEXT,\n            confidence TEXT,\n            pinned INTEGER NOT NULL DEFAULT 0,\n            created_at INTEGER NOT NULL\n        )
table|merge_candidates|merge_candidates|CREATE TABLE merge_candidates (\n            id TEXT PRIMARY KEY,\n            artifact_id TEXT NOT NULL UNIQUE,\n            staging_branch TEXT NOT NULL,\n            state TEXT NOT NULL DEFAULT 'pending'\n                CHECK (state IN ('pending','merged','rejected')),\n            merged_sha TEXT,\n            created_at INTEGER NOT NULL\n        )
table|messages|messages|CREATE TABLE messages (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            session_id TEXT NOT NULL,\n            role TEXT NOT NULL,\n            content TEXT NOT NULL CHECK (json_valid(content)),\n            engine TEXT,\n            agent_id TEXT,\n            agent_name_snapshot TEXT,\n            -- 刀 R P0-2：防重复写键（可空·NULL 不参与下方部分唯一索引）。\n            dedup_key TEXT,\n            -- msgfix1 T2（M0 §10.7）：该消息内容版本唯一真相源。新建行默认 1，每次 content 原地更新点原子 +1（见 update_dispatch_card_terminal / update_decision_card_status）。\n            revision INTEGER NOT NULL DEFAULT 1,\n            created_at INTEGER NOT NULL\n        )
table|messages_fts|messages_fts|CREATE VIRTUAL TABLE messages_fts USING fts5(\n    message_id UNINDEXED,\n    session_id UNINDEXED,\n    text,\n    tokenize = 'trigram'\n)
table|messages_fts_config|messages_fts_config|CREATE TABLE 'messages_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID
table|messages_fts_content|messages_fts_content|CREATE TABLE 'messages_fts_content'(id INTEGER PRIMARY KEY, c0, c1, c2)
table|messages_fts_data|messages_fts_data|CREATE TABLE 'messages_fts_data'(id INTEGER PRIMARY KEY, block BLOB)
table|messages_fts_docsize|messages_fts_docsize|CREATE TABLE 'messages_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)
table|messages_fts_idx|messages_fts_idx|CREATE TABLE 'messages_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID
table|namespaces|namespaces|CREATE TABLE namespaces (\n            id TEXT PRIMARY KEY,\n            kind TEXT NOT NULL\n                CHECK (kind IN ('local', 'github_org')),\n            name TEXT NOT NULL,\n            is_builtin INTEGER NOT NULL DEFAULT 0,\n            last_active_repo_id TEXT,\n            added_at INTEGER NOT NULL,\n            last_used_at INTEGER\n        )
table|project_intro|project_intro|CREATE TABLE project_intro (\n                repo_id TEXT PRIMARY KEY REFERENCES repos(id) ON DELETE CASCADE,\n                content TEXT NOT NULL,\n                generated_at INTEGER NOT NULL,\n                head_sha TEXT NOT NULL\n            )
table|project_remote_rooms|project_remote_rooms|CREATE TABLE project_remote_rooms (\n            project_id TEXT PRIMARY KEY,\n            room_id TEXT NOT NULL UNIQUE,\n            created_at_ms INTEGER NOT NULL\n        )
table|remote_devices|remote_devices|CREATE TABLE remote_devices (\n            device_id TEXT PRIMARY KEY,\n            name TEXT NOT NULL DEFAULT '',\n            token_hash TEXT NOT NULL,\n            refresh_hash TEXT NOT NULL,\n            access_expires_at INTEGER NOT NULL,\n            created_at INTEGER NOT NULL,\n            revoked_at INTEGER\n        , room_id TEXT, generation INTEGER, refresh_until INTEGER, journal_request_id TEXT, journal_generation INTEGER, journal_prev_generation INTEGER, journal_prev_access_hash TEXT, journal_prev_refresh_hash TEXT, journal_response_ct TEXT, journal_response_n TEXT, journal_prev_expires_at INTEGER, journal_response_expires INTEGER)
table|remote_inbox|remote_inbox|CREATE TABLE remote_inbox (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            session_id TEXT NOT NULL,\n            command_id TEXT NOT NULL UNIQUE,\n            kind TEXT NOT NULL,\n            payload TEXT NOT NULL,\n            created_at INTEGER NOT NULL,\n            delivered_at INTEGER,\n            attempts INTEGER NOT NULL DEFAULT 0,\n            failed_at INTEGER,\n            last_error TEXT\n        )
table|remote_registry_counter|remote_registry_counter|CREATE TABLE remote_registry_counter (\n            room_id TEXT PRIMARY KEY,\n            next_generation INTEGER NOT NULL CHECK (next_generation > 0)\n        )
table|repos|repos|CREATE TABLE repos (\n            id TEXT PRIMARY KEY,\n            source TEXT NOT NULL DEFAULT 'local'\n                CHECK (source IN ('local', 'github')),\n            owner TEXT,\n            name TEXT NOT NULL,\n            path TEXT NOT NULL UNIQUE,\n            status TEXT NOT NULL DEFAULT 'active'\n                CHECK (status IN ('active', 'archived', 'invalid')),\n            added_at INTEGER NOT NULL,\n            last_used_at INTEGER\n        , icon TEXT, namespace_id TEXT NOT NULL DEFAULT 'local' REFERENCES namespaces(id) ON DELETE CASCADE)
table|reviews|reviews|CREATE TABLE reviews (\n            id TEXT PRIMARY KEY,\n            artifact_id TEXT NOT NULL,\n            reviewer_agent TEXT NOT NULL,\n            advisory INTEGER NOT NULL DEFAULT 1,\n            verdict TEXT NOT NULL DEFAULT 'pending'\n                CHECK (verdict IN ('pending','pass','fail')),\n            notes TEXT,\n            created_at INTEGER NOT NULL\n        )
table|run_commit_intents|run_commit_intents|CREATE TABLE run_commit_intents (\n            session_id TEXT NOT NULL,\n            run_id TEXT NOT NULL,\n            expected_head TEXT NOT NULL,\n            previous_state TEXT NOT NULL,\n            created_at INTEGER NOT NULL,\n            PRIMARY KEY (session_id, run_id)\n        )
table|run_commits|run_commits|CREATE TABLE run_commits (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            session_id TEXT NOT NULL,\n            run_id TEXT NOT NULL,\n            engine TEXT NOT NULL,\n            pre_head TEXT NOT NULL,\n            post_head TEXT,\n            commit_sha TEXT,\n            files_changed INTEGER,\n            insertions INTEGER,\n            deletions INTEGER,\n            interrupted INTEGER NOT NULL DEFAULT 0,\n            state TEXT NOT NULL DEFAULT 'running'\n                CHECK (state IN ('running', 'active', 'failed', 'undone', 'kept', 'discarded')),\n            created_at INTEGER NOT NULL,\n            UNIQUE (session_id, run_id)\n        )
table|session_agent_configs|session_agent_configs|CREATE TABLE session_agent_configs (\n            session_id TEXT PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE,\n            lead_agent_id TEXT REFERENCES agents(id) ON DELETE SET NULL,\n            member_agent_ids TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(member_agent_ids))\n        )
table|session_groups|session_groups|CREATE TABLE session_groups (\n            id TEXT PRIMARY KEY,\n            namespace_id TEXT NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,\n            repo_id TEXT NOT NULL REFERENCES repos(id) ON DELETE CASCADE,\n            name TEXT NOT NULL,\n            position INTEGER NOT NULL DEFAULT 0,\n            created_at INTEGER NOT NULL\n        )
table|session_runtime|session_runtime|CREATE TABLE session_runtime (\n            session_id TEXT PRIMARY KEY,\n            status TEXT NOT NULL CHECK (status IN ('running', 'idle')),\n            run_id TEXT,\n            updated_at INTEGER NOT NULL\n        )
table|sessions|sessions|CREATE TABLE sessions (\n            id TEXT PRIMARY KEY,\n            title TEXT NOT NULL,\n            created_at INTEGER NOT NULL,\n            total_input_tokens INTEGER NOT NULL DEFAULT 0,\n            total_output_tokens INTEGER NOT NULL DEFAULT 0\n        , repo_id TEXT REFERENCES repos(id) ON DELETE SET NULL, namespace_id TEXT DEFAULT 'local' REFERENCES namespaces(id) ON DELETE SET NULL, group_id TEXT REFERENCES session_groups(id) ON DELETE SET NULL, git_state TEXT NOT NULL DEFAULT 'clean', parent_session_id TEXT, continued_to_session_id TEXT, pinned INTEGER NOT NULL DEFAULT 0, unread INTEGER NOT NULL DEFAULT 0, archived INTEGER NOT NULL DEFAULT 0, archived_at INTEGER, deleted_at INTEGER, workspace_scope TEXT)
table|sqlite_sequence|sqlite_sequence|CREATE TABLE sqlite_sequence(name,seq)
table|team_run_pending|team_run_pending|CREATE TABLE team_run_pending (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            session_id TEXT NOT NULL,\n            run_id TEXT NOT NULL UNIQUE,\n            goal TEXT,\n            lead_participant_id TEXT,\n            assignments_json TEXT NOT NULL DEFAULT '[]',\n            started_at INTEGER NOT NULL,\n            state TEXT NOT NULL DEFAULT 'running' CHECK (state IN ('running','interrupted','done')),\n            created_at INTEGER NOT NULL\n        )
table|verifications|verifications|CREATE TABLE verifications (\n            id TEXT PRIMARY KEY,\n            artifact_id TEXT NOT NULL,\n            cmd TEXT NOT NULL,\n            artifact_sha TEXT NOT NULL,\n            exit_code INTEGER,\n            output_ref TEXT,\n            verdict TEXT NOT NULL DEFAULT 'pending'\n                CHECK (verdict IN ('pending','passed','failed')),\n            created_at INTEGER NOT NULL\n        )
trigger|messages_fts_ad|messages|CREATE TRIGGER messages_fts_ad AFTER DELETE ON messages BEGIN\n            DELETE FROM messages_fts WHERE message_id = OLD.id;\n         END
trigger|messages_fts_ai|messages|CREATE TRIGGER messages_fts_ai AFTER INSERT ON messages BEGIN\n            INSERT INTO messages_fts (message_id, session_id, text)\n            SELECT NEW.id, NEW.session_id, group_concat(json_extract(block.value, '$.text'), char(10)) FROM json_each(NEW.content) block WHERE block.type = 'object' AND json_extract(block.value, '$.type') = 'text' HAVING count(*) > 0;\n         END
trigger|messages_fts_au|messages|CREATE TRIGGER messages_fts_au AFTER UPDATE OF content ON messages BEGIN\n            DELETE FROM messages_fts WHERE message_id = OLD.id;\n            INSERT INTO messages_fts (message_id, session_id, text)\n            SELECT NEW.id, NEW.session_id, group_concat(json_extract(block.value, '$.text'), char(10)) FROM json_each(NEW.content) block WHERE block.type = 'object' AND json_extract(block.value, '$.type') = 'text' HAVING count(*) > 0;\n         END
PRAGMA user_version|1
